diff --git a/src/config.js b/src/config.js
index 726fdca..0a5865f 100644
--- a/src/config.js
+++ b/src/config.js
@@ -1,7 +1,21 @@
+function isPlainObject(value) {
+	return value !== null && typeof value === "object" && Object.getPrototypeOf(value) === Object.prototype;
+}
+
 /**
- * Returns the configuration `defaults` with `overrides` applied: each key of `overrides` replaces the default value.
+ * Returns the configuration `defaults` with `overrides` applied.
+ * Nested plain objects merge key by key; other override values replace defaults.
  * Neither argument is modified.
  */
 export function mergeConfig(defaults, overrides) {
-	return { ...defaults, ...overrides };
+	const result = { ...defaults, ...overrides };
+
+	for (const key of Reflect.ownKeys(overrides ?? {})) {
+		if (!Object.prototype.propertyIsEnumerable.call(overrides, key)) continue;
+		if (isPlainObject(defaults?.[key]) && isPlainObject(overrides[key])) {
+			result[key] = mergeConfig(defaults[key], overrides[key]);
+		}
+	}
+
+	return result;
 }
diff --git a/test/config.test.js b/test/config.test.js
index 0ef0b7d..a7c270c 100644
--- a/test/config.test.js
+++ b/test/config.test.js
@@ -17,3 +17,22 @@ test("nested objects merge key by key", () => {
 		level: "info",
 	});
 });
+
+test("plain objects merge at arbitrary depth without modifying inputs", () => {
+	const defaults = { server: { tls: { enabled: true, port: 443 }, host: "localhost" } };
+	const overrides = { server: { tls: { port: 8443 } } };
+	const originalDefaults = structuredClone(defaults);
+	const originalOverrides = structuredClone(overrides);
+	assert.deepEqual(mergeConfig(defaults, overrides), {
+		server: { tls: { enabled: true, port: 8443 }, host: "localhost" },
+	});
+	assert.deepEqual(defaults, originalDefaults);
+	assert.deepEqual(overrides, originalOverrides);
+});
+
+test("non-object overrides replace nested defaults", () => {
+	for (const value of [["c"], null, "disabled", 0]) {
+		assert.deepEqual(mergeConfig({ option: { enabled: true } }, { option: value }), { option: value });
+	}
+	assert.deepEqual(mergeConfig({ tags: ["a", "b"] }, { tags: ["c"] }), { tags: ["c"] });
+});

diff --git a/src/config.js b/src/config.js
index 726fdca..2365d9e 100644
--- a/src/config.js
+++ b/src/config.js
@@ -1,7 +1,29 @@
+function isPlainObject(value) {
+	return value !== null && typeof value === "object" && Object.getPrototypeOf(value) === Object.prototype;
+}
+
 /**
- * Returns the configuration `defaults` with `overrides` applied: each key of `overrides` replaces the default value.
+ * Returns the configuration `defaults` with `overrides` applied.
+ * Nested plain objects merge key by key; other override values replace the default.
  * Neither argument is modified.
  */
 export function mergeConfig(defaults, overrides) {
-	return { ...defaults, ...overrides };
+	const merged = { ...defaults, ...overrides };
+
+	for (const key of Reflect.ownKeys(Object(overrides))) {
+		if (!Object.prototype.propertyIsEnumerable.call(overrides, key)) continue;
+
+		const defaultValue = defaults?.[key];
+		const overrideValue = overrides[key];
+		if (isPlainObject(defaultValue) && isPlainObject(overrideValue)) {
+			Object.defineProperty(merged, key, {
+				value: mergeConfig(defaultValue, overrideValue),
+				writable: true,
+				enumerable: true,
+				configurable: true,
+			});
+		}
+	}
+
+	return merged;
 }
diff --git a/test/config.test.js b/test/config.test.js
index 0ef0b7d..755dc9c 100644
--- a/test/config.test.js
+++ b/test/config.test.js
@@ -17,3 +17,33 @@ test("nested objects merge key by key", () => {
 		level: "info",
 	});
 });
+
+test("plain objects merge at multiple depths", () => {
+	assert.deepEqual(
+		mergeConfig(
+			{ server: { tls: { enabled: true, cert: "default.pem" }, port: 8080 } },
+			{ server: { tls: { cert: "custom.pem" } } },
+		),
+		{ server: { tls: { enabled: true, cert: "custom.pem" }, port: 8080 } },
+	);
+});
+
+test("non-object overrides replace nested defaults", () => {
+	for (const replacement of [["c"], null, "disabled", 0, false]) {
+		assert.deepEqual(
+			mergeConfig({ options: { enabled: true }, tags: ["a", "b"] }, { options: replacement, tags: ["c"] }),
+			{ options: replacement, tags: ["c"] },
+		);
+	}
+});
+
+test("merging does not modify either argument", () => {
+	const defaults = Object.freeze({ server: Object.freeze({ host: "localhost", port: 8080 }) });
+	const overrides = Object.freeze({ server: Object.freeze({ port: 9090 }) });
+	const merged = mergeConfig(defaults, overrides);
+	assert.deepEqual(merged, { server: { host: "localhost", port: 9090 } });
+	assert.notEqual(merged.server, defaults.server);
+	assert.notEqual(merged.server, overrides.server);
+	assert.equal(defaults.server.port, 8080);
+	assert.deepEqual(overrides.server, { port: 9090 });
+});
